package kome.client;
import java.lang.reflect.Field;
import java.util.*;
import kome.common.KOMEAccessFixture;
import kome.common.data.*;
import kome.common.network.*;
import io.netty.buffer.*;
import lotr.client.gui.LOTRGuiMap;
import org.junit.Test;
import static org.junit.Assert.*;

public class KOMEProgressionCoherencePresentationTest {
    @Test public void nameplateUsesServerSuffixPreservesNativeNicknameAndNeverChangesProfile()throws Exception{KOMEAccessFixture f=new KOMEAccessFixture();java.lang.reflect.Field profileField=net.minecraft.entity.player.EntityPlayer.class.getDeclaredField("field_146106_i");profileField.setAccessible(true);com.mojang.authlib.GameProfile original=new com.mojang.authlib.GameProfile(f.player.id,"OriginalPlayer");profileField.set(f.player,original);String profile=f.player.getGameProfile().getName();KOMEPlayerNameplate.update(Collections.singletonMap(f.player.getUniqueID(),KOMEProgressionIdentity.suffix("rohan",KOMEProgressionRank.KNIGHT)));assertTrue(KOMEPlayerNameplate.format("Nickname",f.player).startsWith("Nickname"));assertTrue(KOMEPlayerNameplate.format("Nickname",f.player).contains(KOMEFactionProgressionTitles.title("rohan",KOMEProgressionRank.KNIGHT)));assertEquals(profile,f.player.getGameProfile().getName());KOMEPlayerNameplate.clear();assertEquals("Nickname",KOMEPlayerNameplate.format("Nickname",f.player));assertEquals(", Wanderer of the Lands",KOMEProgressionIdentity.suffix("",KOMEProgressionRank.WANDERER));}
    @Test public void publicIdentityPacketRoundTripsUuidAndFormatting(){UUID id=UUID.randomUUID();KOMEPacketProgressionIdentities a=new KOMEPacketProgressionIdentities(Collections.singletonMap(id,", Wanderer of the Lands"));ByteBuf b=Unpooled.buffer();a.toBytes(b);KOMEPacketProgressionIdentities c=new KOMEPacketProgressionIdentities();c.fromBytes(b);assertEquals(a.suffixes,c.suffixes);assertEquals(0,b.readableBytes());}
    @Test public void factionQualifiedTitlesAreNotRepeatedAndNativeLanguageKeysNeverLeak(){assertEquals(", Rider of Rohan",KOMEProgressionIdentity.suffix("rohan",KOMEProgressionRank.KNIGHT));assertFalse(KOMEProgressionIdentity.suffix("gondor",KOMEProgressionRank.KNIGHT).contains("lotr.faction."));}
    @Test public void authoritativeNegativeEligibilityAndReasonRemainCachedAndUpdateAutomatically(){KOMEStandingTrialEligibilityState s=new KOMEStandingTrialEligibilityState();UUID id=UUID.randomUUID();s.update(7,id,false,false,true,"You have already attempted a trial today.");assertTrue(s.isRelevant(7,id));assertFalse(s.isEligible(7,id));assertTrue(s.reason(7,id).contains("today"));s.update(7,id,true,true,true,"");assertTrue(s.isStandingTrialAvailable(7,id,false));assertEquals("",s.reason(7,id));assertFalse(s.isRelevant(8,id));s.clear();assertFalse(s.isRelevant(7,id));}
    @Test public void eligibilityPacketTransportsRelevantDisabledReason(){KOMEPacketStandingTrialEligibility a=new KOMEPacketStandingTrialEligibility(5,UUID.randomUUID(),false,false,false,0);a.relevant=true;a.reason="You must wait before approaching this lord again.";ByteBuf b=Unpooled.buffer();a.toBytes(b);KOMEPacketStandingTrialEligibility c=new KOMEPacketStandingTrialEligibility();c.fromBytes(b);assertTrue(c.relevant);assertFalse(c.eligible);assertEquals(a.reason,c.reason);assertEquals(0,b.readableBytes());}
    @Test public void showMeUsesNativeMaximumZoomAndStableCamera()throws Exception{LOTRGuiMap map=KOMEAccessFixture.allocate(LOTRGuiMap.class);KOMEVisualMarker marker=new KOMEVisualMarker(KOMEVisualMarker.Role.COMMISSION,"","Objective","",100,12345,0,-6789);KOMEProgressionMapFocus.focus(map,marker);assertEquals(4,field("zoomPower").getInt(map));assertEquals(4,field("prevZoomPower").getInt(map));assertEquals(0,field("zoomTicks").getInt(map));assertEquals(16F,field("zoomScale").getFloat(map),0F);assertEquals(KOMEProgressionMapFocus.mapX(marker.x),field("posX").getFloat(map),0F);KOMEProgressionMapFocus.highlight(marker,0);assertTrue(KOMEProgressionMapFocus.isFocused(marker,9999999999L));assertFalse(KOMEProgressionMapFocus.isFocused(marker,10000000000L));}
    private static Field field(String name)throws Exception{Field f=LOTRGuiMap.class.getDeclaredField(name);f.setAccessible(true);return f;}
    @Test public void enemyOutlineExcludesOrdinaryAndIncidentalEnemiesAndClearsWithObjective(){String bound=UUID.randomUUID().toString();KOMEVisualMarkerClientState.update(Collections.singletonList(new KOMEVisualMarker(KOMEVisualMarker.Role.ENCOUNTER_ENEMY,bound,"Attacker","",100,0,65,0)));assertTrue(KOMEProgressionEnemyOutline.relevant(bound,100,40*40));assertFalse(KOMEProgressionEnemyOutline.relevant(UUID.randomUUID().toString(),100,40*40));assertFalse(KOMEProgressionEnemyOutline.relevant(bound,100,4*4));assertFalse(KOMEProgressionEnemyOutline.relevant(bound,101,40*40));KOMEVisualMarkerClientState.clear();assertFalse(KOMEProgressionEnemyOutline.relevant(bound,100,40*40));}
}
